installFakeDom();
const flush=async()=>{for(let i=0;i<40;i++)await Promise.resolve();};
const descriptor=(petId,provider,adapter,name=petId)=>({schemaVersion:1,petId,kind:'llm',name,lifecycle:'active',binding:{provider,adapter,model:'private-profile'},configurationAvailable:true,capabilities:[{id:'goals.draft',support:'supported'}]});
const originalGoal=()=>({schemaVersion:4,id:'native-goal',revision:'r1',sequence:1,createdAt:1,updatedAt:1,spec:{requestId:'request',owner:{petId:'ai_ollama',provider:'ollama',adapter:'ollama'},context:{kind:'unbound'},intent:'Original background objective',criteria:['Original criterion']},state:'draft',tasks:[],plans:[],admissions:[],events:[],legacy:[]});
const button=(view,text)=>view.el.find('button').find(b=>b.textContent===text);
test('peer resumption review presents the retained limits and destination without starting a driver',async()=>{
 const f=mock(),g=originalGoal(),prepare=Bridge.petRuntimePreparePeerResume,confirm=Bridge.petRuntimeConfirmRecovery,sent=[];
 g.state='recoveryRequired';g.admissions=[{spec:{schemaVersion:3,decisionId:'same-decision',planningPolicy:{catalog:'peerDelegationIterationV1'}},phase:'recoveryRequired',lease:{id:'same-lease'}}];f.setGoal(g);
 const r={goalId:g.id,petId:g.spec.owner.petId,goalRevision:g.revision,model:'original-model',originalBudget:{deadlineAt:Date.now()+60_000},remaining:{modelCalls:0,toolCalls:1,outputBytes:1024},delegatedHeld:{modelCalls:1,toolCalls:1,outputBytes:2048},pendingSteps:[{stepId:'pending'}],receipts:[{messageId:'confirmed'}],additionalAllowance:false,modelUseAuthorized:false,lastReviewedDestination:{kind:'server',provider:'ollama',endpoint:'http://127.0.0.1:19009',model:'original-model'}};
 Bridge.petRuntimePreparePeerResume=async input=>{sent.push(['prepare',structuredClone(input)]);return{status:'review',ticket:{token:'scoped-native-owner',proposal:{goalId:g.id,petId:g.spec.owner.petId,revision:g.revision,provider:'ollama',approvalScope:'resumeOriginalPeerExecution',resultingState:'leased',intent:g.spec.intent,criteria:g.spec.criteria,snapshot:{accounting:null},peerResumption:r}}};};
 Bridge.petRuntimeConfirmRecovery=async input=>{sent.push(['confirm',structuredClone(input)]);return{status:'declined'};};const view=buildRuntimeGoals();
 try{view.setActive(true);await flush();const review=button(view,'Rever retoma do objetivo');assert.equal(review.hidden,false);assert.equal(sent.length,0);review.fire('click');await flush();assert.equal(sent.length,1);assert.equal(sent[0][1].revision,g.revision);assert.match(view.el.textContent,/Saldo livre: 0 chamadas ao modelo/);assert.match(view.el.textContent,/Reservado para filhos: 1 chamadas ao modelo/);assert.match(view.el.textContent,/127\.0\.0\.1:19009/);assert.match(view.el.textContent,/Sem orçamento adicional ou consentimento de dados reconstruído/);assert.ok(button(view,'Confirmar retoma do objetivo'));button(view,'Recusar retoma não publicada').fire('click');await flush();assert.equal(sent[1][1].approve,false);assert.ok(!f.calls.some(([name])=>['start-driver','claim','inference'].includes(name)));}
 finally{view.dispose();Bridge.petRuntimePreparePeerResume=prepare;Bridge.petRuntimeConfirmRecovery=confirm;f.restore();}
});
test('recovery control: Pause keeps the original owner and revision while the selected pet changes',async()=>{
 const f=mock(),g=originalGoal(),saved=Bridge.petRuntimeMutate,sent=[];
 g.state='recoveryRequired';g.admissions=[{spec:{schemaVersion:21,decisionId:'recovered-parent'},phase:'recoveryRequired',lease:{id:'original-closed-lease'}}];f.setGoal(g);
 let release;const waiting=new Promise(resolve=>{release=resolve;});
 Bridge.petRuntimeMutate=async input=>{sent.push(structuredClone(input));await waiting;return{status:'durable',record:structuredClone(g)};};
 let sequence=0;const view=buildRuntimeGoals({ids:()=>`recovery-control-${++sequence}`});
 try{
  view.setActive(true);await flush();const pause=button(view,'Pausar / interromper');assert.equal(pause.hidden,false);assert.equal(pause.disabled,false);
  pause.fire('click');await flush();assert.equal(sent.length,1);
  const pet=view.el.find('select').find(n=>n.getAttribute('aria-label')==='Pet responsável pelo objetivo');pet.value='agent_codex';pet.fire('change');await flush();
  assert.equal(sent[0].petId,g.spec.owner.petId);assert.equal(sent[0].goalId,g.id);assert.equal(sent[0].revision,g.revision);assert.deepEqual(sent[0].action,{kind:'pause'});assert.match(sent[0].requestId,/^recovery-control-/);
  assert.ok(!sent.some(i=>i.action.kind==='resumeDraft'));assert.ok(!f.calls.some(([k])=>['inference','goal-answer','terminal-answer'].includes(k)));
 }finally{release();await flush();view.dispose();Bridge.petRuntimeMutate=saved;f.restore();}
});
