  button(view,'Retirar autorização não utilizada').fire('click');await flush();assert.equal(sent.length,3);f.setGoal({...g,revision:'newer-goal',state:'cancelled'});await view.refresh();await flush();assert.match(view.el.textContent,/revisão anterior/);button(view,'Retirar autorização não utilizada').fire('click');await flush();assert.deepEqual(sent[2],sent[3]);assert.equal(sent[3][1].revision,g.revision);assert.equal(sent[3][1].decisionId,'second-unused');assert.equal(sent[3][1].token,'original-retirement-token');assert.ok(!f.calls.some(c=>['create','context','mutate','metadata','inference','goal-answer'].includes(c[0])));
