function mock(){
 const saved={},calls=[];let goal=originalGoal(),next=1,pending=[];const fns={
  async petRuntimeGoalPending(){calls.push(['pending']);return structuredClone(pending);},
  async petRuntimeList(){calls.push(['list']);return {schemaVersion:1,complete:true,unavailable:0,pendingArtifacts:0,goals:goal?[{id:goal.id,revision:goal.revision,petId:goal.spec.owner.petId}]:[]};},
  async petRuntimeRead(){calls.push(['read']);return structuredClone(goal);},
  async petCapabilities(){calls.push(['capabilities']);return {pets:[descriptor('ai_ollama','ollama','ollama','Local helper'),descriptor('agent_codex','codex','codex','Codex helper'),descriptor('agent_antigravity','antigravity','antigravity','Gravity helper'),descriptor('agent_copilot','copilot','copilot','Copilot helper')]};},
  async petRuntimeCreate(input){calls.push(['create',structuredClone(input)]);goal={...originalGoal(),id:'new-native-goal',spec:{...originalGoal().spec,requestId:input.requestId,owner:{petId:input.petId,provider:input.petId==='agent_codex'?'codex':'ollama',adapter:input.petId==='agent_codex'?'codex':'ollama'},intent:input.intent,criteria:structuredClone(input.criteria)}};return {status:'durable',record:structuredClone(goal)};},
  async petRuntimeMutate(input){calls.push(['mutate',structuredClone(input)]);if(input.action.kind==='proposeTask')goal.tasks=[{id:'native-task',description:input.action.description,state:'proposed',planId:null}];if(input.action.kind==='proposePlan'){goal.plans=[{id:'native-plan',taskId:input.action.taskId,steps:input.action.steps.map((s,i)=>({...s,id:`step-${i}`,state:'proposed'}))}];goal.tasks[0].planId='native-plan';}goal.revision=`r${++next}`;return {status:'durable',record:structuredClone(goal)};},
  async petRuntimePrepareContext(input){calls.push(['context',structuredClone(input)]);goal.executionContext={mode:input.mode,conversationId:'private-native-context'};goal.revision=`r${++next}`;return {status:'durable',record:structuredClone(goal)};},
  async petRuntimeGoalAnswer(...input){calls.push(['goal-answer',structuredClone(input)]);},
  async cliAgentAnswer(...input){calls.push(['terminal-answer',structuredClone(input)]);throw Error('must never answer a terminal through goal controls');},
  async petRuntimeRefreshReadiness(...input){calls.push(['metadata',structuredClone(input)]);},
  async petRuntimeRespondOnce(...input){calls.push(['inference',structuredClone(input)]);throw Error('unexpected inference');},
 };
 for(const [key,value]of Object.entries(fns)){saved[key]=Bridge[key];Bridge[key]=value;}
 return {calls,setGoal(value){goal=structuredClone(value);},setPending(value){pending=structuredClone(value);},restore(){for(const[key,value]of Object.entries(saved))Bridge[key]=value;},get goal(){return structuredClone(goal);}};
}
